-- =============================================================================
-- CMK migration 003 — format_specs seeds for the 11 SPEC formats (HE + EN)
-- Requires 002_spec_formats.sql. Idempotent (ON CONFLICT DO NOTHING).
--
-- * text_post + carousel on LinkedIn: is_active = true, is_stub = false (v0 path).
-- * The other 9 formats: is_stub = true, is_active = false. Structure + rules only.
--   A stub can't be activated (CHECK format_specs_stub_inactive); Itay reviews,
--   sets is_stub=false, then is_active=true and format_registry.v0_enabled=true.
-- * Every rule has a source: 'guardian_rules' (existing doc), 'house_default'
--   (our starting choice, tune with data) or 'platform_limit_verify' (re-check
--   against the platform's current docs before enabling; limits_verified=false).
-- * No client facts, pricing or numbers about Itay's business are seeded here.
-- =============================================================================
BEGIN;
SET search_path = cmk, public;
SET LOCAL cmk.actor_type = 'human';   -- audit_log: seeds are applied by a human operator
SET LOCAL cmk.actor_name = 'migration_003';

INSERT INTO format_specs (format, channel, language, version, is_active, is_stub, min_chars, max_chars, max_slides, min_duration_s, max_duration_s, aspect_ratio, min_items, max_items, item_max_chars, requires_media, limits_verified, structure, rules, notes)
VALUES ('text_post', 'linkedin', 'en', 1, true, false, 600, 2200, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false,
  '[{"section": "hook", "desc": "first 1-2 lines, works before ''see more''; first line <=120 chars"}, {"section": "situation", "desc": "evidence/scene first"}, {"section": "pattern", "desc": "name the working pattern, not a person''s flaw"}, {"section": "move", "desc": "one reversible move"}, {"section": "cta", "desc": "closing question; optional P.S. soft offer"}]'::jsonb,
  '[{"rule": "Hard max 3,000 chars (B-11).", "severity": "block", "source": "platform_limit_verify"}, {"rule": "Paragraphs <=3 lines / <=350 chars.", "severity": "warn", "source": "house_default"}, {"rule": "Links go in first comment.", "severity": "warn", "source": "house_default"}, {"rule": "<=3 hashtags, <=3 emojis.", "severity": "warn", "source": "house_default"}, {"rule": "Every number/claim maps to an approved+public fact in fact_ids (Guardian B-01).", "severity": "block", "source": "guardian_rules"}, {"rule": "No pricing, client names, testimonials or viewer data (B-02/B-03/B-04/B-12).", "severity": "block", "source": "guardian_rules"}, {"rule": "One closing question about the reader''s own team/decision/process (CTA §8).", "severity": "warn", "source": "guardian_rules"}, {"rule": "EN: zero Hebrew characters; one spelling system.", "severity": "block", "source": "guardian_rules"}]'::jsonb,
  'v0 active recipe. Primary channel; other channels in format_registry.default_channels get their own rows when enabled.')
ON CONFLICT (format, channel, language, version) DO NOTHING;

